import React from 'react';
import { cn } from '@/lib/utils';

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, type = 'text', label, error, id, ...props }, ref) => {
    const inputId = id || (label ? label.toLowerCase().replace(/\s+/g, '-') : undefined);

    return (
      <div className="w-full space-y-1.5">
        {label && (
          <label htmlFor={inputId} className="block text-xs font-medium text-[#8B949E]">
            {label}
          </label>
        )}
        <input
          id={inputId}
          type={type}
          ref={ref}
          className={cn(
            'w-full px-3 py-2 bg-[#0D1117] border border-[#30363D] text-white text-sm rounded-[6px] placeholder-[#6E7681]',
            'transition-colors duration-150',
            'focus:outline-none focus:border-[#00FF87] focus:ring-1 focus:ring-[#00FF87]',
            error && 'border-[#FF4D4F] focus:border-[#FF4D4F] focus:ring-[#FF4D4F]',
            className
          )}
          {...props}
        />
        {error && <p className="text-xs text-[#FF4D4F] mt-1">{error}</p>}
      </div>
    );
  }
);

Input.displayName = 'Input';
